import { mkdir, readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const canonicalPath = path.join(
  repoRoot,
  "packages/contracts/fixtures/mobile-wire-v1.json"
);
const generatedPath = path.join(
  repoRoot,
  "mobile/voxagent-companion/src/api/fixtures/mobile-wire-v1.generated.ts"
);

const canonical = await readFile(canonicalPath, "utf8");
const parsed = JSON.parse(canonical);
const generated = [
  "// Generated by scripts/mobile_contract_fixtures.mjs. Do not edit.",
  `export default ${JSON.stringify(parsed, null, 2)} as const;`,
  "",
].join("\n");

if (process.argv.includes("--write")) {
  await mkdir(path.dirname(generatedPath), { recursive: true });
  await writeFile(generatedPath, generated, "utf8");
  process.stdout.write(`updated ${path.relative(repoRoot, generatedPath)}\n`);
} else if (process.argv.includes("--check")) {
  const current = await readFile(generatedPath, "utf8").catch(() => "");
  if (current !== generated) {
    process.stderr.write(
      "Mobile contract fixture mirror is stale. Run npm run contracts:mobile-fixtures:sync.\n"
    );
    process.exitCode = 1;
  } else {
    process.stdout.write("Mobile contract fixture mirror is current.\n");
  }
} else {
  process.stderr.write(
    "Usage: node scripts/mobile_contract_fixtures.mjs --check|--write\n"
  );
  process.exitCode = 2;
}
